#pragma once
#include "Common.h"
namespace hub {
inline JsonObject catalogTask(std::wstring mode,JsonObject input){auto folder=dataDir()/L"plugin-library";std::filesystem::create_directories(folder);auto nonce=std::to_wstring(GetTickCount64());auto request=folder/(nonce+L"-request.json"),reply=folder/(nonce+L"-result.json");write(request,std::wstring(input.Stringify()));auto exe=binaryDir()/L"Hhub.Catalog.exe";auto command=L"\""+exe.wstring()+L"\" "+mode+L" \""+request.wstring()+L"\" \""+reply.wstring()+L"\"";STARTUPINFOW si{sizeof(si)};si.dwFlags=STARTF_USESHOWWINDOW;si.wShowWindow=SW_HIDE;PROCESS_INFORMATION pi{};if(!CreateProcessW(exe.c_str(),command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,binaryDir().c_str(),&si,&pi))throw hresult_error(E_FAIL,L"插件库服务无法启动");CloseHandle(pi.hThread);auto status=WaitForSingleObject(pi.hProcess,60000);if(status!=WAIT_OBJECT_0){TerminateProcess(pi.hProcess,1);CloseHandle(pi.hProcess);throw hresult_error(E_FAIL,L"插件库连接超时");}CloseHandle(pi.hProcess);auto result=object(read(reply));std::error_code ec;std::filesystem::remove(request,ec);std::filesystem::remove(reply,ec);return result;}
inline JsonObject catalogConfig(){auto file=dataDir()/L"plugin-library"/L"source.json";if(std::filesystem::exists(file)){auto config=object(read(file));if(!str(config,L"indexUrl").empty())return config;}file=binaryDir()/L"plugin-library-source.json";return std::filesystem::exists(file)?object(read(file)):object(LR"({"repository":"shengerq/H-hub-plugins","indexUrl":"https://raw.githubusercontent.com/shengerq/H-hub-plugins/main/index.json"})");}
inline JsonObject cachedCatalog(){auto file=dataDir()/L"plugin-library"/L"catalog.json";if(!std::filesystem::exists(file))file=binaryDir()/L"plugin-library-cache.json";return std::filesystem::exists(file)?object(read(file)):object(L"{\"plugins\":[]}");}
}
